    {
      "id": "3",
      "type": "code",
      "param": {
        "variables": [["extracted_text", ["text", "2"]]],
        "outputs": [["json_data", "array[object]"], ["categories", "array[string]"], ["values", "array[number]"]],
        "code": "import csv\nfrom io import StringIO\n\ndef main(extracted_text: str):\n    f = StringIO(extracted_text)\n    reader = csv.DictReader(f)\n    json_data = [row for row in reader]\n    # Simple heuristic: first column -> categories, second column -> numeric values\n    headers = list(json_data[0].keys()) if json_data else []\n    categories = [row[headers[0]] for row in json_data] if len(headers) >= 1 else []\n    values   = [float(row[headers[1]]) for row in json_data if str(row[headers[1]]).replace('.', '', 1).isdigit()] if len(headers) >= 2 else []\n    return {\"json_data\": json_data, \"categories\": categories, \"values\": values}"
      }
    },
    {
      "id": "4",
      "type": "if-else",
      "param": {
        "cases": [
          [null, [[["chart_type", "1"], "not empty"]]],
          [null, [[["chart_type", "1"], "empty"]]]
        ]
