        "outputs": [["file_structure", "string"]],
        "code": "import json\nimport requests\n\ndef build_tree_string(owner_repo, path='', prefix=''):\n    url = f\"https://api.github.com/repos/{owner_repo}/contents/{path}\"\n    try:\n        response = requests.get(url)\n        response.raise_for_status()\n        items = response.json()\n        \n        lines = []\n        items = sorted(items, key=lambda x: (x['type'] != 'dir', x['name']))\n        \n        for i, item in enumerate(items):\n            is_last = i == len(items) - 1\n            if item['type'] == 'dir':\n                lines.append(f\"{prefix}{'└── ' if is_last else '├── '}{item['name']}/\")\n                extension = '    ' if is_last else '│   '\n                sub_lines = build_tree_string(owner_repo, item['path'], prefix + extension)\n                lines.extend(sub_lines)\n            else:\n                lines.append(f\"{prefix}{'└── ' if is_last else '├── '}{item['name']}\")\n        \n        return lines\n    except Exception as e:\n        return [f\"Error: {str(e)}\"]\n\ndef main(api_response, repo_path):\n    try:\n        tree_lines = build_tree_string(repo_path)\n        tree_string = '\\n'.join(tree_lines)\n        return {\n            \"file_structure\": tree_string\n        }\n    except Exception as e:\n        return {\n            \"file_structure\": f\"Error generating tree: {str(e)}\"\n        }"
