        "variables": [["llm_response", ["text", "3"]], ["q1", ["question_1", "1"]], ["q2", ["question_2", "1"]]],
        "outputs": [["result", "array[object]"]],
        "code": "def main(llm_response: str, q1: str, q2: str):
	lines = llm_response.strip().split('\n')
	results = []
	current_q = None
	current_a = None
	current_e = None

	for line in lines:
		line = line.strip()
		if line.startswith('QUESTION 1:'):
			current_q = q1
		elif line.startswith('ANSWER 1:'):
			current_a = line[9:].strip()
		elif line.startswith('EVIDENCE 1:'):
			current_e = line[11:].strip()
			if current_q and current_a and current_e:
				results.append({
					"question": current_q,
					"answer": current_a,
					"evidence": current_e
				})
		elif line.startswith('QUESTION 2:'):
			current_q = q2
		elif line.startswith('ANSWER 2:'):
			current_a = line[9:].strip()
		elif line.startswith('EVIDENCE 2:'):
